local Players = game:GetService( "Players" );
local ReplicatedStorage = game:GetService( "ReplicatedStorage" );

local Root = Players.LocalPlayer.Character:WaitForChild( "HumanoidRootPart" );
local GameMap = game:GetService( "Workspace" ):WaitForChild( "Map" ):WaitForChild( "Ingame" ):WaitForChild( "Map" );

local Enabled = true;
local IsFixingGenerator = false; -- should be false. read the code
local Cooldown = 1.5; -- MAX value btw. (less then that is ban..)

--67.6942% is vibecoded! (i really dont gonna work really hard for this.)

--below that. if u change = ban
--if u know what are u doing then change.

local function check()
    local PuzzleUI = Players.LocalPlayer:WaitForChild( "PlayerGui" ):FindFirstChild( "PuzzleUI" );
    local RefPuzzleUI = ReplicatedStorage:FindFirstChild( "PuzzleUI", true );
    if not IsFixingGenerator or not PuzzleUI then
        return true;
    end;
    local pGui = PuzzleUI:FindFirstChildWhichIsA( "GuiObject" );
    local rGui = RefPuzzleUI and RefPuzzleUI:FindFirstChildWhichIsA( "GuiObject" );
    if not pGui or not rGui then
        return true;
    end;
    return pGui.Size ~= rGui.Size or not Enabled;
end;

Players.LocalPlayer.CharacterAdded:Connect( function( c )
    Root = c:WaitForChild( "HumanoidRootPart" );
end );

task.spawn( function()
    while task.wait() do
        if not Enabled or IsFixingGenerator or not Root or not GameMap then
            continue;
        end;
        for _, Object in GameMap:QueryDescendants( "Model#Generator:has(#Main)" ) do
            local Main = Object:FindFirstChild( "Main" );
            if Main and ( Main.Position - Root.Position ).Magnitude < 6.7 then--yes. this the value.
                task.spawn( function()
                    IsFixingGenerator = true;
                    local RemoteEvent = Object:FindFirstChild( "Remotes" ) and Object:FindFirstChild( "Progress" ) and Object.Remotes:FindFirstChildOfClass( "RemoteEvent" ); -- important
                    if RemoteEvent and Players.LocalPlayer:WaitForChild( "PlayerGui" ):FindFirstChild( "PuzzleUI" ) then -- important. (visual.)
                        while true do
                            if check() then break end;
                            task.wait( Cooldown );
                            if check() then break end;
                            RemoteEvent:FireServer();
                        end;
                    end;
                    IsFixingGenerator = false;
                end );
                break;
            end;
        end;
    end;
end );
